/**
 * secret 様 token の runtime 非依存 policy SSoT。
 *
 * lint / feedback / state-db のいずれにも所有させず、依存方向を
 * 各機能 module -> security の一方向に保つ。
 */
export const SECRET_PATTERN =
  /(\bsk-[A-Za-z0-9_-]{16,}|\bghp_[A-Za-z0-9_]{16,}|\bgithub_pat_[A-Za-z0-9_]{16,}|\bxox[baprs]-[A-Za-z0-9-]{16,})/;

export function isSecretLike(value: string): boolean {
  return SECRET_PATTERN.test(value);
}

/** secret-egress hook runner — raw secret 値を出力せず write / Git egress 前に遮断する。 */
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";
import { analyzeSecretScan, type SecretScanArtifact } from "../security/secret-policy";
import { extractShellCommand } from "./git-command-guard";

export interface SecretEgressHookOutcome {
  exitCode: 0 | 2;
  message?: string;
  checked?: number;
}

function block(artifacts: readonly SecretScanArtifact[]): SecretEgressHookOutcome {
  const result = analyzeSecretScan(artifacts, { allowAnnotatedExamples: false });
  if (result.ok) return { exitCode: 0, checked: result.checked };
  const sample = result.violations
    .slice(0, 8)
    .map((finding) => `${finding.path}:${finding.line}:${finding.marker}`)
    .join(", ");
  return {
    exitCode: 2,
    checked: result.checked,
    message:
      `[helix-secret-egress-guard] BLOCK: secret-like material ${result.violations.length}件 ` +
      `(${sample})。値は表示していません。credentialをsecret storeへ移し、露出済みならrotateしてください。`,
  };

export const SECURITY_CREDENTIAL_EGRESS_GUARD_SCHEMA_VERSION =
  "security-credential-egress-guard.v1";

export type EgressPolicy = "offline" | "allowlist" | "undefined";
export type ActivationKind = "none" | "external_api" | "auth" | "infra";

export interface ToolEgressCheckInput {
  tool_name: string;
  external: boolean;
  egress_policy?: EgressPolicy | null;
  allowed_hosts?: string[];
  args?: string[];
  activation_kind?: ActivationKind;
  action_binding_approval_present?: boolean;
}

export interface SecurityCredentialEgressGuardReport {
  schema_version: typeof SECURITY_CREDENTIAL_EGRESS_GUARD_SCHEMA_VERSION;
  ok: boolean;
  dry_run: true;
  credential_contract: {
    scoped_token_only: true;
    no_raw_secret_exposure: true;
    broker_required_for_external_auth: true;
  };

const SECRET_LIKE_RE =
  /\b[A-Za-z0-9_-]*(?:token|api[_-]?key|secret|password|passwd|pwd|bearer)[A-Za-z0-9_-]*\s*[=:]\s*\S+/i;

export function buildSecurityCredentialEgressGuardReport(
  input: ToolEgressCheckInput,
  options: { sourceCommand?: string } = {},

export function attestWorkerIsolationPolicy(
  request: WorkerIsolationPolicyRequest,
): WorkerIsolationPolicyResult {
  if (!isWrapperLaunchExecution(request.wrapperLaunch)) {
    return policyFailure("WORKER_ISOLATION_POLICY_UNRESOLVED");
  }
  if (
    request.task_sensitivity !== "non_secret" ||
    isSecretLike(request.wrapperLaunch.stdin ?? "") ||
    request.wrapperLaunch.invocation.args.some((argument) => isSecretLike(argument))
  ) {
    return policyFailure("WORKER_ISOLATION_SECRET_TASK_DENIED");
  }
